#!/usr/bin/env bash
# Run the project's full test suite: the fast and browser tiers, every test except those tagged [slow].
# Extra arguments pass to node --test. Generated by /task-setup.
set -euo pipefail
cd "$(dirname "$0")/../.."
exec node --test --test-concurrency=2 --test-timeout=180000 --test-skip-pattern="\[slow\]" "tests/**/*.test.mjs" "$@"
